// JourneyServiceServer is the server API for JourneyService service.
// All implementations must embed UnimplementedJourneyServiceServer
// for forward compatibility.
//
// JourneyService is the wire form of the Promotion journey engine port
// (internal/humanwork/workspace.JourneyEngine): one governed promotion
// followed from the manager's proposal, through the P1B execution authority
// gate, to the routed approver's decision and the one ledger fact the
// workflow's END node records. It exists so the browser-resident
// GoWebComponents/WASM journey page can read and act through exactly the
// engine operations the workspace surface uses, over the gRPC-over-WebSocket
// tunnel, with no HTTP/JSON business surface in between: Protobuf/gRPC is the
// canonical contract for this page as it is for every other.
//
// Every message here mirrors a workspace port type field for field. This
// service invents no HCM meaning of its own: the stage is derived by the
// engine from durable state (the intent record, the workflow instance, its
// work items and the ledger), never asserted by the page, and every write is
// one of the engine's own governed operations rather than a table update.
//
// JourneyService is hosted by the same process as
// hcmnext.intents.v1.IntentService and hcmnext.admin.v1.AdminService
// (internal/transport/journey.Register adds it to the shared *grpc.Server the
// modular application already builds via
// internal/transport/grpcserver.NewServer) and reuses that server's whole
// trusted-request boundary unchanged: the same transport.Admit admission
// steps, the same deadline cap, the same envelope.Error projection. Unlike
// AdminService there is no additional per-method role predicate: the journey
// page is an ordinary authenticated surface, and every authorization decision
// is made by the engine behind the port, which refuses under the same policy
// the RPC surfaces would (workspace.ErrDenied projects to PERMISSION_DENIED).
//
// Fourteen methods are unary and WatchJourney is server-streaming. The stream
// is admitted exactly as the unary methods are: the shared trusted-request
// boundary is installed by grpcserver.NewServer as both
// grpc.ChainUnaryInterceptor(grpcserver.UnaryInterceptor) and
// grpc.ChainStreamInterceptor(grpcserver.StreamInterceptor), and the two
// interceptors run the same transport.Admit, the same deadline cap and the
// same envelope.Error projection over the same code. A streaming handler
// therefore sees an admitted trust.Principal and transport.Invocation in
// its context exactly as a unary one does.
type JourneyServiceServer interface {
	// ListJourneys returns every promotion journey in the caller's tenant,
	// newest first. Effect class: READ_ONLY. It forwards to
	// workspace.JourneyEngine.ListJourneys, which reads the intent records and
	// derives each journey's stage from durable state; nothing is written and
	// no capability runs.
	ListJourneys(context.Context, *ListJourneysRequest) (*ListJourneysResponse, error)
	// ProposeJourney creates and simulates a new promotion intent from the
	// manager's input. Effect class: governed write through the intent service
	// - workspace.JourneyEngine.Propose runs the engine's own CreateIntent
	// followed by SimulateIntent, so the proposal is minted as an immutable
	// revision with a material digest exactly as any other intent is. It
	// returns the journey at JOURNEY_STAGE_PROPOSED, or
	// JOURNEY_STAGE_BLOCKED when the simulation produced no executable plan.
	// Nothing about the worker's current placement, pay or budget authority is
	// read from this request: the engine reads those through the governed
	// worker read.
	ProposeJourney(context.Context, *ProposeJourneyRequest) (*ProposeJourneyResponse, error)
	// ProposePromotion is the intent-only `promotion.propose` request contract
	// (PROMO-007). It is the same governed act ProposeJourney performs -
	// CapabilityGateway -> the application Promotion service -> IntentService ->
	// preflight - stated as a closed contract rather than as a page form, so
	// that a browser, a CLI, an agent and a partner connector all invoke one
	// semantic capability and none of them can say anything the server owns.
	//
	// The difference from ProposeJourney is the request message, and it is the
	// whole point. ProposePromotionRequest carries exactly the caller's
	// intention: who the subject is, what is desired for them, when it takes
	// effect, why, which subject revision the intention was formed against and
	// which client request this is. It carries no current salary, no current
	// manager, no position vacancy, no budget envelope and no authority
	// assertion, because those are facts this cell resolves server-side through
	// the governed reads; and it carries no principal, tenant, session, locale
	// or legal-context selector, because those are derived from the verified
	// credential by the trusted-request boundary and are not a caller's to
	// choose. There is nowhere in this message to put such a fact, and a caller
	// that appends one as an unknown or extension field is refused
	// INVALID_ARGUMENT rather than having it ignored - a silently dropped
	// assertion is indistinguishable, to the caller, from an accepted one. That
	// refusal is the shared trusted-request boundary's own strict decoding
	// (internal/transport.Validate, rule strict_decoding.unknown_field), so it
	// is identical on both transports because it is the same code on both; the
	// application service refuses the same bytes again for a caller that reaches
	// it in-process.
	//
	// Effect class: governed write through the intent service, exactly as
	// ProposeJourney's. Propose and its preflight simulation mutate no domain
	// state: what they record is chronology (the intent) and what they compute
	// is a proposal.
	ProposePromotion(context.Context, *ProposePromotionRequest) (*ProposePromotionResponse, error)
	// InspectJourney returns everything durable about one journey: the
	// summary, the simulation findings and planned writes, the workflow
	// instance and its node executions, the work items and their transitions,
	// the ledger fact, the recorded evidence identifiers and the
	// engine-composed timeline. Effect class: READ_ONLY. It forwards to
	// workspace.JourneyEngine.Inspect and writes nothing.
	InspectJourney(context.Context, *InspectJourneyRequest) (*InspectJourneyResponse, error)
	// ExecuteJourney runs the engine's ExecuteIntent for an approved,
	// re-simulated proposal. Effect class: governed write behind the P1B
	// execution authority gate - workspace.JourneyEngine.Execute is refused
	// with UNAVAILABLE when the cell was not composed with that authority
	// (cmd/hcmnext -execution-authority=true), and with FAILED_PRECONDITION
	// when the journey is not at a stage from which execution is available. On
	// success the workflow instance exists and is parked on its approval
	// WorkItem, and the returned detail carries it.
	ExecuteJourney(context.Context, *ExecuteJourneyRequest) (*ExecuteJourneyResponse, error)
	// DecideJourney records the routed approver's decision. Effect class:
	// governed write through the WorkItem store and the caller-driven
	// execution driver - workspace.JourneyEngine.Decide claims and completes
	// the approval WorkItem as the routed approver, then resumes the driver,
	// which runs the instance to its APPROVED or REJECTED terminal and, on
	// approval, records the one ledger fact the END node raises. A caller who
	// is not the routed approver is refused PERMISSION_DENIED by the engine,
	// not by this service.
	DecideJourney(context.Context, *DecideJourneyRequest) (*DecideJourneyResponse, error)
	// EditProposal corrects an unstarted or not-yet-approved promotion
	// proposal (PROMOUX-013). Effect class: governed write through the intent
	// service - it is workspace.JourneyEngine.EditProposal, which is
	// [CancelIntent] plus a fresh ProposeJourney, not SupersedeIntent:
	// promote_worker's own declared lifecycle transitions
	// (definitions.simulateOnlyChangeTransitions) reach SUPERSEDED only from
	// SIMULATED, SUBMITTED or APPROVED, and a journey's stored intent never
	// durably leaves DRAFT (SimulateIntent persists nothing), so
	// SupersedeIntent is structurally unusable here. EditProposal instead
	// cancels the original first - the same governed disposition CancelIntent
	// already reports, safe-point-aware for a mid-flight journey exactly as
	// RequestJourneyIntervention's CANCEL kind is - and only once that
	// disposition reports the original genuinely and cleanly stopped
	// (CANCELLED) does it mint the edited successor through the ordinary
	// ProposeJourney path. Any other disposition (CANCELLATION_PENDING,
	// TOO_LATE, REPAIR_REQUIRED) refuses the edit outright rather than minting
	// a successor next to an original that was not actually stopped. Because
	// the original carries any recorded approval and the original is what is
	// durably cancelled, the successor inherits nothing from it, including no
	// approval - which is how an edit invalidates material approvals. A
	// caller presenting a stale expected_instance_version, or naming an
	// already-terminal original, is refused FAILED_PRECONDITION.
	EditProposal(context.Context, *EditProposalRequest) (*EditProposalResponse, error)
	// PreviewJourneyIntervention answers, for one journey and one typed
	// intervention kind (WITHDRAW or CANCEL), whether the intervention is
	// available right now, and if not, why - by a stable reason reference
	// computed only from the journey's own durable stage. Effect class:
	// READ_ONLY. It mutates nothing and runs no capability; a caller not
	// authorized to read this journey at all is refused exactly as
	// InspectJourney would refuse them (NOT_FOUND or PERMISSION_DENIED),
	// before this method's own logic ever runs - so the presence or shape of
	// a preview answer never discloses more than InspectJourney already
	// would.
	PreviewJourneyIntervention(context.Context, *PreviewJourneyInterventionRequest) (*PreviewJourneyInterventionResponse, error)
	// RequestJourneyIntervention runs a typed WITHDRAW (before any approval)
	// or CANCEL (during an eligible wait) intervention. Effect class:
	// governed write through the intent service - it is
	// workspace.JourneyEngine.RequestIntervention, which is [CancelIntent]
	// scoped to journeys: both kinds are the same governed capability,
	// reporting the same four dispositions CancelIntent already reports
	// (CANCELLED, CANCELLATION_PENDING, TOO_LATE, REPAIR_REQUIRED) projected
	// onto the shared hcmnext.common.v1.InterventionOutcome vocabulary; Kind
	// only selects which stages [PreviewJourneyIntervention] offers the
	// action at. A caller who races this call against a concurrent approval,
	// timer fire or terminal commit is resolved to exactly one durable
	// outcome by the intent record's own optimistic instance-version
	// compare-and-swap - the same single serialization point CancelIntent and
	// SupersedeIntent already use - so no partial domain write is possible: a
	// losing caller's request never touches durable state at all.
	RequestJourneyIntervention(context.Context, *RequestJourneyInterventionRequest) (*RequestJourneyInterventionResponse, error)
	// WatchJourney is a server-streaming change feed over the same read
	// InspectJourney performs. Effect class: READ_ONLY.
	//
	// The semantics are exactly these. The server emits the journey's current
	// detail once immediately, unless since_digest equals the digest that
	// current detail already carries, in which case the client is holding it
	// and the initial emission is skipped. After that it emits one message per
	// change: it re-reads the engine on a fixed short interval and sends only
	// when JourneyDetail.detail_digest differs from the digest it last sent.
	// An unchanged journey therefore produces no traffic at all - there is no
	// heartbeat message and no "nothing changed" message to filter out.
	//
	// The stream ends in one of three ways. The client cancels, which is the
	// ordinary case and is not an error. The server's fifteen-minute stream
	// ceiling elapses, which ends the stream with OK - a client that still
	// wants to watch simply opens another stream, carrying the digest it now
	// holds as since_digest so it is not re-sent what it already has. Or the
	// engine refuses the read, which ends the stream with that refusal
	// projected through the owned error model exactly as InspectJourney's
	// would be. The request's own gRPC deadline and the server's deadline cap
	// still apply and still win whenever they are shorter than the ceiling.
	WatchJourney(*WatchJourneyRequest, grpc.ServerStreamingServer[WatchJourneyResponse]) error
	// ListWorkers returns every employee a journey can be proposed for --
	// the release's fixed corpus population and the tenant's own created one,
	// newest created first -- together with the closed set of placements a new
	// employee may be given. Effect class: READ_ONLY. It forwards to
	// workspace.JourneyEngine.ListWorkers, which reads the corpus and the
	// durable journey_worker rows; nothing is written and no capability runs.
	//
	// The options travel in the same response as the list because they are what
	// makes the list actionable: a client holding one and not the other can
	// render a picker but not a form.
	ListWorkers(context.Context, *ListWorkersRequest) (*ListWorkersResponse, error)
	// CreateWorker records one new employee as a durable, append-only fact.
	// Effect class: governed demo-authority write - workspace.JourneyEngine
	// .CreateWorker is gated by the same P1B execution authority ExecuteJourney
	// and DecideJourney run behind, because creating the subject of a promotion
	// is a workforce change and a surface that could do it without that
	// authority would be a way around the gate rather than a step before it.
	//
	// It is refused UNAVAILABLE when this process was composed without the
	// engine, or when the composed cell has no execution database to record a
	// worker in; PERMISSION_DENIED when the caller does not carry the operator
	// role that authority names; and INVALID_ARGUMENT, naming the field, when a
	// name is missing, the base pay is not a positive decimal, the hire date is
	// not an ISO-8601 date, or the placement lands outside every pay band the
	// simulation knows -- which would otherwise produce a worker whose every
	// promotion is refused later for a reason that has nothing to do with the
	// promotion.
	CreateWorker(context.Context, *CreateWorkerRequest) (*CreateWorkerResponse, error)
	// GetProductPreferences returns the authenticated user's presentation
	// defaults together with the authenticated organization's shared
	// appearance. Tenant, organization scope, and principal are derived from
	// the admitted credential, never from fields in this request. Effect class:
	// READ_ONLY.
	GetProductPreferences(context.Context, *GetProductPreferencesRequest) (*GetProductPreferencesResponse, error)
	// SaveUserPreferences replaces the authenticated user's presentation
	// defaults under optimistic versioning. It cannot alter another user's
	// record because neither tenant nor principal is accepted on the wire.
	SaveUserPreferences(context.Context, *SaveUserPreferencesRequest) (*SaveUserPreferencesResponse, error)
	// SaveTenantAppearance replaces organization-wide branding under optimistic
	// versioning. The organization scope comes from the admitted credential and
	// the server additionally requires the comp_admin role. The RPC name is kept
	// for wire compatibility.
	SaveTenantAppearance(context.Context, *SaveTenantAppearanceRequest) (*SaveTenantAppearanceResponse, error)
	// SaveOrganizationVisibility replaces the organization-wide directory
	// visibility boundary under optimistic versioning. The organization scope
	// is derived from the admitted credential and comp_admin is required.
	SaveOrganizationVisibility(context.Context, *SaveOrganizationVisibilityRequest) (*SaveOrganizationVisibilityResponse, error)
	// GetRoleAccess returns the tenant role catalog, employee assignments, and
	// one organization-directory policy per role. Only HCM administrators can
	// read or mutate this administrative projection.
	GetRoleAccess(context.Context, *GetRoleAccessRequest) (*GetRoleAccessResponse, error)
	SaveAccessRole(context.Context, *SaveAccessRoleRequest) (*SaveAccessRoleResponse, error)
	SaveWorkerRoleAssignment(context.Context, *SaveWorkerRoleAssignmentRequest) (*SaveWorkerRoleAssignmentResponse, error)
	SaveRoleOrganizationVisibility(context.Context, *SaveRoleOrganizationVisibilityRequest) (*SaveRoleOrganizationVisibilityResponse, error)
	SaveRolePagePermission(context.Context, *SaveRolePagePermissionRequest) (*SaveRolePagePermissionResponse, error)
	SaveRoleFeaturePermission(context.Context, *SaveRoleFeaturePermissionRequest) (*SaveRoleFeaturePermissionResponse, error)
	// RecordWorkflowUse increments the authenticated user's usage count for a
	// workflow so launchers can rank real frequent actions rather than hardcode
	// a single action. It grants no authority to run the named workflow.
	RecordWorkflowUse(context.Context, *RecordWorkflowUseRequest) (*RecordWorkflowUseResponse, error)
	// GetWorkerIDPolicy returns the authenticated organization's formatting
	// and allocation state. It requires the compensation administrator role.
	GetWorkerIDPolicy(context.Context, *GetWorkerIDPolicyRequest) (*GetWorkerIDPolicyResponse, error)
	// SaveWorkerIDPolicy replaces configurable formatting rules under
	// optimistic versioning. Allocation state can never be moved backwards.
	SaveWorkerIDPolicy(context.Context, *SaveWorkerIDPolicyRequest) (*SaveWorkerIDPolicyResponse, error)
	mustEmbedUnimplementedJourneyServiceServer()
}

